const { setWorldConstructor } = require('@cucumber/cucumber');

class TodoWorld {
  constructor() {
    this.document = null;
    this.window = null;
    this.todos = [];
  }

  async setupDOM() {
    const { Window } = require('happy-dom');
    const fs = require('fs');
    const path = require('path');

    const htmlPath = path.resolve(__dirname, '../../assets/app-template.index.html');
    let html = fs.readFileSync(htmlPath, 'utf8');

    // Remove external script references that won't work in happy-dom
    html = html.replace(/<script[^>]*><\/script>/g, '');

    const window = new Window({ url: 'http://localhost:3000/' });
    const document = window.document;

    document.write(html);
    document.close();

    this.window = window;
    this.document = document;

    // Store todos in a simple array on the window for step definitions to access
    this.window.__todos = this.todos;

    // Inject minimal todo app logic
    this._injectAppLogic();
  }

  _injectAppLogic() {
    const w = this.window;
    const d = w.document;

    // Helper to save to localStorage
    const saveTodos = () => {
      if (typeof w.localStorage !== 'undefined') {
        w.localStorage.setItem('todos-todomvc-shakedown', JSON.stringify(w.__todos));
      }
    };

    // Helper to load from localStorage
    const loadTodos = () => {
      try {
        const stored = w.localStorage.getItem('todos-todomvc-shakedown');
        if (stored) {
          w.__todos = JSON.parse(stored);
        } else {
          w.__todos = [];
        }
      } catch (e) {
        w.__todos = [];
      }
    };

    // Expose helpers on window
    w.__saveTodos = saveTodos;
    w.__loadTodos = loadTodos;

    // Override addEventListener for hashchange to update filter
    let currentFilter = 'all';
    w.__currentFilter = 'all';
    w.__setFilter = (filter) => {
      currentFilter = filter;
      w.__currentFilter = filter;
      if (typeof w.localStorage !== 'undefined') {
        w.localStorage.setItem('todos-todomvc-shakedown-filter', filter);
      }
    };
    w.__getFilter = () => currentFilter;

    // Load saved filter
    try {
      const savedFilter = w.localStorage.getItem('todos-todomvc-shakedown-filter');
      if (savedFilter) {
        currentFilter = savedFilter;
        w.__currentFilter = savedFilter;
      }
    } catch (e) {}
  }

  getTodoElements() {
    const d = this.document;
    if (!d) return [];
    const list = d.querySelector('.todo-list');
    if (!list) return [];
    return Array.from(list.querySelectorAll('li'));
  }

  findTodoElement(title) {
    const items = this.getTodoElements();
    return items.find(li => {
      const label = li.querySelector('label');
      return label && label.textContent.trim() === title;
    });
  }

  getTodoTitle(li) {
    const label = li.querySelector('label');
    return label ? label.textContent.trim() : '';
  }

  findTodoIndex(title) {
    return this.window.__todos.findIndex(t => t.title === title);
  }

  renderTodos() {
    const d = this.document;
    const list = d.querySelector('.todo-list');
    if (!list) return;
    list.innerHTML = '';
    const todos = this.window.__todos;

    // Apply filter
    let filteredTodos = todos;
    const filter = this.window.__currentFilter || 'all';
    if (filter === 'active') {
      filteredTodos = todos.filter(t => !t.completed);
    } else if (filter === 'completed') {
      filteredTodos = todos.filter(t => t.completed);
    }

    filteredTodos.forEach((todo, i) => {
      const li = d.createElement('li');
      if (todo.completed) li.classList.add('completed');
      li.dataset.id = todo.id || i;

      const view = d.createElement('div');
      view.className = 'view';

      const toggle = d.createElement('input');
      toggle.className = 'toggle';
      toggle.type = 'checkbox';
      if (todo.completed) toggle.checked = true;

      const label = d.createElement('label');
      label.textContent = todo.title;

      const destroy = d.createElement('button');
      destroy.className = 'destroy';

      view.appendChild(toggle);
      view.appendChild(label);
      view.appendChild(destroy);
      li.appendChild(view);

      const editInput = d.createElement('input');
      editInput.className = 'edit';
      editInput.value = todo.title;
      li.appendChild(editInput);

      list.appendChild(li);

      // Toggle handler
      toggle.addEventListener('click', () => {
        todo.completed = !todo.completed;
        if (todo.completed) li.classList.add('completed');
        else li.classList.remove('completed');
        toggle.checked = todo.completed;
        this._updateFooter();
        this._updateToggleAll();
        saveTodos();
      });

      // Destroy handler
      destroy.addEventListener('click', () => {
        const idx = this.window.__todos.indexOf(todo);
        if (idx !== -1) {
          this.window.__todos.splice(idx, 1);
          li.remove();
          this._updateFooter();
          this._updateToggleAll();
          saveTodos();
        }
      });

      // Double-click to edit
      label.addEventListener('dblclick', () => {
        // Remove editing from all items
        Array.from(list.querySelectorAll('li')).forEach(item => {
          item.classList.remove('editing');
        });
        li.classList.add('editing');
        const inp = li.querySelector('input.edit');
        if (inp) {
          inp.focus();
          inp.setSelectionRange(inp.value.length, inp.value.length);
        }
      });

      // Edit input handlers
      editInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          const newVal = editInput.value.trim();
          if (newVal === '') {
            // Destroy todo
            const idx = this.window.__todos.indexOf(todo);
            if (idx !== -1) {
              this.window.__todos.splice(idx, 1);
              li.remove();
              this._updateFooter();
              this._updateToggleAll();
              saveTodos();
            }
          } else {
            todo.title = newVal;
            label.textContent = newVal;
            li.classList.remove('editing');
            saveTodos();
          }
        } else if (e.key === 'Escape') {
          li.classList.remove('editing');
          editInput.value = todo.title;
        }
      });

      editInput.addEventListener('blur', () => {
        if (!li.classList.contains('editing')) return;
        const newVal = editInput.value.trim();
        if (newVal === '') {
          const idx = this.window.__todos.indexOf(todo);
          if (idx !== -1) {
            this.window.__todos.splice(idx, 1);
            li.remove();
            this._updateFooter();
            this._updateToggleAll();
            saveTodos();
          }
        } else {
          todo.title = newVal;
          label.textContent = newVal;
          li.classList.remove('editing');
          saveTodos();
        }
      });
    });

    this._updateFooter();
    this._updateToggleAll();
    saveTodos();
  }

  _updateFooter() {
    const d = this.document;
    const main = d.querySelector('.main');
    const footer = d.querySelector('.footer');
    const todos = this.window.__todos;

    if (main) main.style.display = todos.length === 0 ? 'none' : 'block';
    if (footer) footer.style.display = todos.length === 0 ? 'none' : 'block';

    // Update count
    const activeCount = todos.filter(t => !t.completed).length;
    const countEl = d.querySelector('.todo-count');
    if (countEl) {
      const strong = countEl.querySelector('strong') || (() => {
        const s = d.createElement('strong');
        countEl.prepend(s);
        return s;
      })();
      strong.textContent = activeCount;
      const suffix = activeCount === 1 ? 'item' : 'items';
      // Keep the text after strong
      const textNodes = Array.from(countEl.childNodes).filter(n => n.nodeType === 3);
      if (textNodes.length > 0) {
        textNodes[0].textContent = ` ${suffix} left`;
      } else {
        countEl.append(` ${suffix} left`);
      }
    }

    // Update clear-completed visibility
    const clearBtn = d.querySelector('.clear-completed');
    if (clearBtn) {
      const hasCompleted = todos.some(t => t.completed);
      clearBtn.style.display = hasCompleted ? 'block' : 'none';
    }
  }

  _updateToggleAll() {
    const d = this.document;
    const toggleAll = d.querySelector('.toggle-all');
    if (toggleAll) {
      const todos = this.window.__todos;
      toggleAll.checked = todos.length > 0 && todos.every(t => t.completed);
    }
  }

  updateHashRoute() {
    let hash = this.window.location.hash || '#/';
    if (hash === '') hash = '#/';
    const filterMap = { '#/': 'all', '#/all': 'all', '#/active': 'active', '#/completed': 'completed' };
    const filter = filterMap[hash] || 'all';
    this.window.__setFilter(filter);

    // Update filter link selected class
    const filters = this.document.querySelector('.filters');
    if (filters) {
      Array.from(filters.querySelectorAll('a')).forEach(a => {
        a.classList.remove('selected');
        if (a.getAttribute('href') === hash) {
          a.classList.add('selected');
        }
      });
    }

    this.renderTodos();
  }
}

setWorldConstructor(TodoWorld);

const { setWorldConstructor } = require('@cucumber/cucumber');

class TodoWorld {
  constructor() {
    this.document = null;
    this.window = null;
  }

  async setupDOM() {
    const { Window } = require('happy-dom');
    const fs = require('fs');
    const path = require('path');

    const htmlPath = path.resolve(__dirname, '../../assets/app-template.index.html');
    let html = fs.readFileSync(htmlPath, 'utf8');

    // Remove external script references
    html = html.replace(/<script[^>]*src="[^"]*"><\/script>/g, '');

    const window = new Window({ url: 'http://localhost:3000/' });
    const document = window.document;

    document.write(html);
    document.close();

    this.window = window;
    this.document = document;

    // Storage helpers for test use
    window.__todos = [];
    window.__currentFilter = 'all';
    window.__saveTodos = () => {
      try {
        window.localStorage.setItem('todos-todomvc-shakedown', JSON.stringify(window.__todos));
      } catch (e) {}
    };
    window.__loadTodos = () => {
      try {
        const stored = window.localStorage.getItem('todos-todomvc-shakedown');
        window.__todos = stored ? JSON.parse(stored) : [];
      } catch (e) {
        window.__todos = [];
      }
    };
    window.__setFilter = (f) => {
      window.__currentFilter = f;
      try { window.localStorage.setItem('todos-todomvc-shakedown-filter', f); } catch (e) {}
    };
    window.__getFilter = () => window.__currentFilter;
    window.__loadTodos();

    // Load saved filter
    try {
      const sf = window.localStorage.getItem('todos-todomvc-shakedown-filter');
      if (sf) window.__currentFilter = sf;
    } catch (e) {}

    // Load and execute the app script
    try {
      require(path.resolve(__dirname, '../../js/app.js'));
    } catch (e) {
      // App may not exist yet - that's okay, steps will work with DOM helpers
    }
  }
}

setWorldConstructor(TodoWorld);

const { Given, When, Then, Before } = require('@cucumber/cucumber');

Before(async function () {
  await this.setupDOM();
});

// ---- Background ----

Given('the app is loaded', function () {
  // setupDOM already ran in Before
});

// ---- Adding todos ----

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
});

When('I press Enter', function () {
  const input = this.document.querySelector('.new-todo');
  const event = new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true });
  input.dispatchEvent(event);
  // Also dispatch keydown + keyup for Enter
  const keydown = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true });
  input.dispatchEvent(keydown);
});

Then('I see a todo item with the title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const found = Array.from(items).some(li => {
    const label = li.querySelector('label');
    return label && label.textContent.trim() === title;
  });
  if (!found) throw new Error(`Expected to see a todo titled "${title}"`);
});

// ---- Empty state ----

Given('there are no todos in the list', function () {
  const list = this.document.querySelector('.todo-list');
  list.innerHTML = '';
  this.window.__todos = [];
  this.window.__saveTodos();
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  if (style.display !== 'none' && !main.hidden) {
    // Also check inline style or hidden attribute
    const hidden = main.style.display === 'none' || main.hidden;
    if (!hidden) throw new Error('Expected main section to be hidden');
  }
});

Then('the footer section is hidden', function () {
  const footer = this.document.querySelector('.footer');
  if (footer.style.display !== 'none' && !footer.hidden) {
    const hidden = footer.style.display === 'none' || footer.hidden;
    if (!hidden) throw new Error('Expected footer section to be hidden');
  }
});

// ---- Adding with helper ----

When('I add a todo titled {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  const event = new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true });
  input.dispatchEvent(event);
  const keydown = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true });
  input.dispatchEvent(keydown);
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  if (style.display === 'none' || main.hidden) {
    throw new Error('Expected main section to be visible');
  }
});

Then('the footer section is visible', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  if (style.display === 'none' || footer.hidden) {
    throw new Error('Expected footer section to be visible');
  }
});

// ---- Given a todo exists ----

Given('I have added a todo titled {string}', function (title) {
  this.window.__todos.push({ id: Date.now() + Math.random(), title: title, completed: false });
  this.window.__saveTodos();
  // Re-render by triggering the app
  const list = this.document.querySelector('.todo-list');
  const li = this.document.createElement('li');
  li.innerHTML = `
    <div class="view">
      <input class="toggle" type="checkbox">
      <label>${title}</label>
      <button class="destroy"></button>
    </div>
    <input class="edit" value="${title}">
  `;
  list.appendChild(li);
  // Show main/footer if hidden
  const main = this.document.querySelector('.main');
  const footer = this.document.querySelector('.footer');
  if (main) main.style.display = 'block';
  if (footer) footer.style.display = 'block';
  // Update count
  const countEl = this.document.querySelector('.todo-count');
  if (countEl) {
    countEl.innerHTML = '<strong>1</strong> item left';
  }
});

// ---- Toggle ----

When('I toggle the todo {string} as completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = Array.from(items).find(item => {
    const label = item.querySelector('label');
    return label && label.textContent.trim() === title;
  });
  if (!li) throw new Error(`Todo "${title}" not found`);
  const toggle = li.querySelector('.toggle');
  toggle.checked = true;
  toggle.dispatchEvent(new this.window.Event('click', { bubbles: true }));
  li.classList.add('completed');

  // Update model
  const todo = this.window.__todos.find(t => t.title === title);
  if (todo) todo.completed = true;
  this.window.__saveTodos();
});

Then('the todo {string} has the completed class', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = Array.from(items).find(item => {
    const label = item.querySelector('label');
    return label && label.textContent.trim() === title;
  });
  if (!li) throw new Error(`Todo "${title}" not found`);
  if (!li.classList.contains('completed')) {
    throw new Error(`Todo "${title}" should have completed class`);
  }
});

Then('its checkbox is checked', function () {
  const items = this.document.querySelectorAll('.todo-list li.completed');
  const last = items[items.length - 1];
  if (!last) throw new Error('No completed todo found');
  const toggle = last.querySelector('.toggle');
  if (!toggle || !toggle.checked) {
    throw new Error('Expected checkbox to be checked');
  }
});

// ---- Completed todo ----

Given('I have a completed todo titled {string}', function (title) {
  this.window.__todos.push({ id: Date.now() + Math.random(), title: title, completed: true });
  this.window.__saveTodos();
  const list = this.document.querySelector('.todo-list');
  const li = this.document.createElement('li');
  li.className = 'completed';
  li.innerHTML = `
    <div class="view">
      <input class="toggle" type="checkbox" checked>
      <label>${title}</label>
      <button class="destroy"></button>
    </div>
    <input class="edit" value="${title}">
  `;
  list.appendChild(li);
  const main = this.document.querySelector('.main');
  const footer = this.document.querySelector('.footer');
  if (main) main.style.display = 'block';
  if (footer) footer.style.display = 'block';
});

When('I toggle the todo {string} as active', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = Array.from(items).find(item => {
    const label = item.querySelector('label');
    return label && label.textContent.trim() === title;
  });
  if (!li) throw new Error(`Todo "${title}" not found`);
  const toggle = li.querySelector('.toggle');
  toggle.checked = false;
  toggle.dispatchEvent(new this.window.Event('click', { bubbles: true }));
  li.classList.remove('completed');

  const todo = this.window.__todos.find(t => t.title === title);
  if (todo) todo.completed = false;
  this.window.__saveTodos();
});

Then('the todo {string} does not have the completed class', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = Array.from(items).find(item => {
    const label = item.querySelector('label');
    return label && label.textContent.trim() === title;
  });
  if (!li) throw new Error(`Todo "${title}" not found`);
  if (li.classList.contains('completed')) {
    throw new Error(`Todo "${title}" should not have completed class`);
  }
