  // Re-render from stored todos
  const todos = this.window.__todos;
  todos.forEach(todo => {
    const li = this.document.createElement('li');
    if (todo.completed) li.classList.add('completed');
    li.innerHTML = `
      <div class="view">
        <input class="toggle" type="checkbox" ${todo.completed ? 'checked' : ''}>
        <label>${todo.title}</label>
        <button class="destroy"></button>
      </div>
      <input class="edit" value="${todo.title}">
    `;
    list.appendChild(li);
  });

  // Update visibility
  const main = this.document.querySelector('.main');
  const footer = this.document.querySelector('.footer');
  if (main) main.style.display = todos.length === 0 ? 'none' : 'block';
  if (footer) footer.style.display = todos.length === 0 ? 'none' : 'block';

  // Update count
  const countEl = this.document.querySelector('.todo-count');
  if (countEl) {
    const activeCount = todos.filter(t => !t.completed).length;
    const suffix = activeCount === 1 ? 'item' : 'items';
    countEl.innerHTML = `<strong>${activeCount}</strong> ${suffix} left`;
  }

  // Update filter link if there's a saved filter
  const filter = this.window.__getFilter();
  const filterLinks = this.document.querySelectorAll('.filters a');
  filterLinks.forEach(a => {
    a.classList.remove('selected');
    const href = a.getAttribute('href');
    if ((filter === 'all' && href === '#/') ||
        (filter === 'active' && href === '#/active') ||
        (filter === 'completed' && href === '#/completed')) {
      a.classList.add('selected');
    }
  });
});

