  // Register click handlers for todo-list items (toggle, destroy)
  this._registerDelegatedHandlers();
}

_registerDelegatedHandlers() {
  const self = this;
  const w = this.window;
  const d = this.document;

  // Delegate click events on todo-list
  const list = d.querySelector('.todo-list');
  if (!list) return;

  list.addEventListener('click', function(e) {
    const target = e.target;
    const li = target.closest('li');
    if (!li) return;
    const titleEl = li.querySelector('label');
    const title = titleEl ? titleEl.textContent.trim() : '';

    if (target.classList.contains('toggle')) {
      // Toggle completed
      const todo = w.__todos.find(function(t) { return t.title === title; });
      if (todo) {
        todo.completed = !todo.completed;
        li.classList.toggle('completed', todo.completed);
        target.checked = todo.completed;
        w.__saveTodos();
        self._updateFooter();
        self._updateToggleAll();
      }
    }

    if (target.classList.contains('destroy')) {
      const idx = w.__todos.findIndex(function(t) { return t.title === title; });
      if (idx !== -1) {
        w.__todos.splice(idx, 1);
        li.remove();
        w.__saveTodos();
        self._updateFooter();
        self._updateToggleAll();
      }
    }
  });

  // Double-click to edit
  list.addEventListener('dblclick', function(e) {
    const target = e.target;
    if (target.tagName !== 'LABEL') return;
    const li = target.closest('li');
    if (!li) return;
    // Remove editing from all items
    Array.from(d.querySelectorAll('.todo-list li')).forEach(function(item) {
      item.classList.remove('editing');
    });
    li.classList.add('editing');
    const editInput = li.querySelector('.edit');
    if (editInput) {
      editInput.focus();
      editInput.setSelectionRange(editInput.value.length, editInput.value.length);
    }
  });

  // Edit input handlers (delegated)
  list.addEventListener('keydown', function(e) {
    const li = e.target.closest('li');
    if (!li || !e.target.classList.contains('edit')) return;
    const titleEl = li.querySelector('label');
    const originalTitle = titleEl ? titleEl.textContent.trim() : '';

    if (e.key === 'Enter') {
      e.preventDefault();
      const newVal = e.target.value.trim();
      const todo = w.__todos.find(function(t) { return t.title === originalTitle; });
      if (!todo) return;
      if (newVal === '') {
        const idx = w.__todos.indexOf(todo);
        if (idx !== -1) {
          w.__todos.splice(idx, 1);
          li.remove();
          w.__saveTodos();
          self._updateFooter();
          self._updateToggleAll();
        }
      } else {
        todo.title = newVal;
        if (titleEl) titleEl.textContent = newVal;
        li.classList.remove('editing');
        w.__saveTodos();
      }
    } else if (e.key === 'Escape') {
      li.classList.remove('editing');
      e.target.value = originalTitle;
    }
  });

  list.addEventListener('blur', function(e) {
    const li = e.target.closest('li');
    if (!li || !e.target.classList.contains('edit')) return;
    if (!li.classList.contains('editing')) return;
    const titleEl = li.querySelector('label');
    const originalTitle = titleEl ? titleEl.textContent.trim() : '';
    const newVal = e.target.value.trim();
    const todo = w.__todos.find(function(t) { return t.title === originalTitle; });
    if (!todo) return;
    if (newVal === '') {
      const idx = w.__todos.indexOf(todo);
      if (idx !== -1) {
        w.__todos.splice(idx, 1);
        li.remove();
        w.__saveTodos();
        self._updateFooter();
        self._updateToggleAll();
      }
    } else {
      todo.title = newVal;
      if (titleEl) titleEl.textContent = newVal;
      li.classList.remove('editing');
      w.__saveTodos();
    }
  }, true);
}

_updateFooter() {
  const w = this.window;
  const d = this.document;
  const main = d.querySelector('.main');
  const footer = d.querySelector('.footer');
  const todos = w.__todos;

  if (main) main.style.display = todos.length === 0 ? 'none' : 'block';
  if (footer) footer.style.display = todos.length === 0 ? 'none' : 'block';

  const activeCount = todos.filter(function(t) { return !t.completed; }).length;
  const countEl = d.querySelector('.todo-count');
  if (countEl) {
    const suffix = activeCount === 1 ? 'item' : 'items';
    countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + suffix + ' left';
  }

  const clearBtn = d.querySelector('.clear-completed');
  if (clearBtn) {
    const hasCompleted = todos.some(function(t) { return t.completed; });
    clearBtn.style.display = hasCompleted ? 'block' : 'none';
  }
}

_updateToggleAll() {
  const d = this.document;
  const toggleAll = d.querySelector('.toggle-all');
  if (toggleAll) {
    const todos = this.window.__todos;
    toggleAll.checked = todos.length > 0 && todos.every(function(t) { return t.completed; });
  }
}

