const { setWorldConstructor } = require('@cucumber/cucumber');

class TodoWorld {
  constructor() {
    this.document = null;
    this.window = null;
  }

  async setupDOM() {
    const { Window } = require('happy-dom');
    const fs = require('fs');
    const path = require('path');

    const htmlPath = path.resolve(__dirname, '../../assets/app-template.index.html');
    let html = fs.readFileSync(htmlPath, 'utf8');

    // Remove external script references
    html = html.replace(/<script[^>]*src="[^"]*"><\/script>/g, '');

    // Remove sample list items from the template
    html = html.replace(/<!-- These are here[\\s\\S]*?<\/li>\s*<\/ul>/g, '<\/ul>');

    const window = new Window({ url: 'http://localhost:3000/' });
    const document = window.document;

    document.write(html);
    document.close();

    this.window = window;
    this.document = document;

    // Storage helpers for test use
    window.__todos = [];
    window.__currentFilter = 'all';
    window.__saveTodos = () => {
      try {
        window.localStorage.setItem('todos-todomvc-shakedown', JSON.stringify(window.__todos));
      } catch (e) {}
    };
    window.__loadTodos = () => {
      try {
        const stored = window.localStorage.getItem('todos-todomvc-shakedown');
        window.__todos = stored ? JSON.parse(stored) : [];
      } catch (e) {
        window.__todos = [];
      }
    };
    window.__setFilter = (f) => {
      window.__currentFilter = f;
      try { window.localStorage.setItem('todos-todomvc-shakedown-filter', f); } catch (e) {}
    };
    window.__getFilter = () => window.__currentFilter;
    window.__loadTodos();

    // Initially hide main/footer since there are no todos
    const mainSection = this.document.querySelector('.main');
    const footerSection = this.document.querySelector('.footer');
    if (mainSection) mainSection.style.display = 'none';
    if (footerSection) footerSection.style.display = 'none';

    // Load saved filter
    try {
      const sf = window.localStorage.getItem('todos-todomvc-shakedown-filter');
      if (sf) window.__currentFilter = sf;
    } catch (e) {}

    // Load and execute the app script in the window context
    try {
      const appCode = fs.readFileSync(path.resolve(__dirname, '../../js/app.js'), 'utf8');
      window.Function('window', 'document', appCode)(window, document);
    } catch (e) {
      // App may not exist yet - that's okay
    }

    // Register delegated handlers for todo-list interactions
    this._registerDelegatedHandlers();
  }

  _registerDelegatedHandlers() {
    const self = this;
    const w = this.window;
    const d = this.document;

    // Handle new-todo Enter key
    const newTodo = d.querySelector('.new-todo');
    if (newTodo) {
      newTodo.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') {
          e.preventDefault();
          const value = this.value.trim();
          if (value === '') return;
          w.__todos.push({ id: Date.now() + Math.random(), title: value, completed: false });
          w.__saveTodos();
          self._renderTodoItem(value, false);
          this.value = '';
          self._updateFooter();
          self._updateToggleAll();
        }
      });
    }

    // Handle toggle-all checkbox
    const toggleAll = d.querySelector('.toggle-all');
    if (toggleAll) {
      toggleAll.addEventListener('change', function() {
        const isChecked = this.checked;
        w.__todos.forEach(function(t) { t.completed = isChecked; });
        w.__saveTodos();
        const items = d.querySelectorAll('.todo-list li');
        items.forEach(function(li) {
          li.classList.toggle('completed', isChecked);
          var toggle = li.querySelector('.toggle');
          if (toggle) toggle.checked = isChecked;
        });
        self._updateFooter();
      });
    }

    // Handle clear-completed button
    const clearBtn = d.querySelector('.clear-completed');
    if (clearBtn) {
      clearBtn.addEventListener('click', function() {
        w.__todos = w.__todos.filter(function(t) { return !t.completed; });
        w.__saveTodos();
        var completedItems = d.querySelectorAll('.todo-list li.completed');
        completedItems.forEach(function(li) { li.remove(); });
        self._updateFooter();
        self._updateToggleAll();
      });
    }

    // Delegate click events on todo-list
    const list = d.querySelector('.todo-list');
    if (!list) return;

    list.addEventListener('click', function(e) {
      var target = e.target;
      var li = target.closest('li');
      if (!li) return;
      var titleEl = li.querySelector('label');
      var title = titleEl ? titleEl.textContent.trim() : '';

      if (target.classList.contains('toggle')) {
        var todo = w.__todos.find(function(t) { return t.title === title; });
        if (todo) {
          todo.completed = !todo.completed;
          li.classList.toggle('completed', todo.completed);
          target.checked = todo.completed;
          w.__saveTodos();
          self._updateFooter();
          self._updateToggleAll();
        }
      }

      if (target.classList.contains('destroy')) {
        var idx = w.__todos.findIndex(function(t) { return t.title === title; });
        if (idx !== -1) {
          w.__todos.splice(idx, 1);
          li.remove();
          w.__saveTodos();
          self._updateFooter();
          self._updateToggleAll();
        }
      }
    });

    // Double-click to edit
    list.addEventListener('dblclick', function(e) {
      var target = e.target;
      if (target.tagName !== 'LABEL') return;
      var li = target.closest('li');
      if (!li) return;
      Array.from(d.querySelectorAll('.todo-list li')).forEach(function(item) {
        item.classList.remove('editing');
      });
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      if (editInput) {
        editInput.focus();
        editInput.setSelectionRange(editInput.value.length, editInput.value.length);
      }
    });

    // Edit input keydown
    list.addEventListener('keydown', function(e) {
      var li = e.target.closest('li');
      if (!li || !e.target.classList.contains('edit')) return;
      var titleEl = li.querySelector('label');
      var originalTitle = titleEl ? titleEl.textContent.trim() : '';

      if (e.key === 'Enter') {
        e.preventDefault();
        var newVal = e.target.value.trim();
        var todo = w.__todos.find(function(t) { return t.title === originalTitle; });
        if (!todo) return;
        if (newVal === '') {
          var idx = w.__todos.indexOf(todo);
          if (idx !== -1) {
            w.__todos.splice(idx, 1);
            li.remove();
            w.__saveTodos();
            self._updateFooter();
            self._updateToggleAll();
          }
        } else {
          todo.title = newVal;
          if (titleEl) titleEl.textContent = newVal;
          li.classList.remove('editing');
          w.__saveTodos();
        }
      } else if (e.key === 'Escape') {
        li.classList.remove('editing');
        e.target.value = originalTitle;
      }
    });

    // Edit input blur
    list.addEventListener('blur', function(e) {
      var li = e.target.closest('li');
      if (!li || !e.target.classList.contains('edit') || !li.classList.contains('editing')) return;
      var titleEl = li.querySelector('label');
      var originalTitle = titleEl ? titleEl.textContent.trim() : '';
      var newVal = e.target.value.trim();
      var todo = w.__todos.find(function(t) { return t.title === originalTitle; });
      if (!todo) return;
      if (newVal === '') {
        var idx = w.__todos.indexOf(todo);
        if (idx !== -1) {
          w.__todos.splice(idx, 1);
          li.remove();
          w.__saveTodos();
          self._updateFooter();
          self._updateToggleAll();
        }
      } else {
        todo.title = newVal;
        if (titleEl) titleEl.textContent = newVal;
        li.classList.remove('editing');
        w.__saveTodos();
      }
    }, true);
  }

  _renderTodoItem(title, completed) {
    var d = this.document;
    var list = d.querySelector('.todo-list');
    var li = d.createElement('li');
    if (completed) li.classList.add('completed');
    li.innerHTML = '<div class="view"><input class="toggle" type="checkbox"' + (completed ? ' checked' : '') + '><label>' + title + '</label><button class="destroy"></button></div><input class="edit" value="' + title + '">';
    list.appendChild(li);
  }

  _updateFooter() {
    var w = this.window;
    var d = this.document;
    var main = d.querySelector('.main');
    var footer = d.querySelector('.footer');
    var todos = w.__todos;

    if (main) main.style.display = todos.length === 0 ? 'none' : 'block';
    if (footer) footer.style.display = todos.length === 0 ? 'none' : 'block';

    var activeCount = todos.filter(function(t) { return !t.completed; }).length;
    var countEl = d.querySelector('.todo-count');
    if (countEl) {
      var suffix = activeCount === 1 ? 'item' : 'items';
      countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + suffix + ' left';
    }

    var clearBtn = d.querySelector('.clear-completed');
    if (clearBtn) {
      var hasCompleted = todos.some(function(t) { return t.completed; });
      clearBtn.style.display = hasCompleted ? 'block' : 'none';
    }
  }

  _updateToggleAll() {
    var d = this.document;
    var toggleAll = d.querySelector('.toggle-all');
    if (toggleAll) {
      var todos = this.window.__todos;
      toggleAll.checked = todos.length > 0 && todos.every(function(t) { return t.completed; });
    }
  }
}

