  });
  if (!link) throw new Error('Filter link "' + filterName + '" not found');
  link.classList.add('selected');
  var href = link.getAttribute('href');
  var filterMap = { '#/': 'all', '#/all': 'all', '#/active': 'active', '#/completed': 'completed' };
  var filter = filterMap[href || '#/'] || 'all';
  this.window.__setFilter(filter);
  filterLinks.forEach(function(a) { if (a !== link) a.classList.remove('selected'); });
});

